mapper.select:
SELECT visitor_id visitorId, `name`, tel, unit, no, invitation_id invitationId, b_id bId
FROM visitor


        visitor_id = #{visitorId}


        AND invitation_id = #{invitationId}


        AND status_cd = #{statusCd}

SELECT b_id bId, visitor_id visitorId, `name`, tel, unit, no, invitation_id invitationId, id_card idCard, license, operate
FROM business_visitor
WHERE b_id = #{bId} AND operate = #{operate}

SELECT t.visitor_id visitorId, t.`name`, t.tel, t.unit, v.visit_type visitType, v.is_come isCome,
v.visit_time visitTime, v.qr_code qrCode, t.id_card idCard
FROM visitor t
LEFT JOIN visit_invitation v ON v.invitation_id = t.invitation_id
WHERE t.status_cd = '0'

    and v.visit_type= #{visitType}


    and v.is_come = #{isCome}


    and v.user_id = #{userId}


    and t.name like concat('%', #{name}, '%')


    and t.unit like concat('%', #{unit}, '%')


    and v.visit_time >=  #{lessVisitTime}


    and v.visit_time <=  #{moreVisitTime}


    and v.community_id = #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

